int phy_highest_priority_CH() {
  if (phy_SINRClass == phy_SINRCLASS_OUTAGE) return phy_CHANNELCLASS_OUTAGE;
  if (phy_PowerClass == phy_POWERCLASS_LOW || phy_PowerClass == phy_POWERCLASS_ABSENT) return phy_CHANNELCLASS_BLOCKAGE;
  if (phy_IClass == phy_ICLASS_HIGH || phy_IClass == phy_ICLASS_CRITICAL) return phy_CHANNELCLASS_INTERFERENCE_LIMITED;
  if (phy_DopplerClass == phy_DOPPLERCLASS_HIGH) return phy_CHANNELCLASS_MOBILITY_LIMITED;
  if (phy_DelaySpreadClass == phy_DELAYSPREADCLASS_HIGH) return phy_CHANNELCLASS_MULTIPATH_LIMITED;
  return phy_CHANNELCLASS_NOMINAL;
}

int phy_highest_priority_SQ() {
  if (phy_ChannelClass == phy_CHANNELCLASS_OUTAGE || phy_SignalClass == phy_SIGNALCLASS_LIMITED || phy_BeamClass == phy_BEAMCLASS_FAILED || phy_PdClass == phy_PDCLASS_FAILED || phy_RfaClass == phy_RFACLASS_CRITICAL || phy_AccClass == phy_ACCCLASS_FAILED || phy_CRBClass == phy_CRBCLASS_UNUSABLE || phy_AoSClass == phy_AOSCLASS_EXPIRED || phy_CapClass == phy_CAPCLASS_FAILED || phy_CoverageClass == phy_COVERAGECLASS_FAILED) return phy_SENSINGSTATE_SENSINGFAILURE;
  if (phy_ChannelClass == phy_CHANNELCLASS_BLOCKAGE || phy_SignalClass == phy_SIGNALCLASS_RECONFIGURING || phy_BeamClass == phy_BEAMCLASS_MISALIGNED) return phy_SENSINGSTATE_FRESHNESSLIMITED;
  if (phy_AoSClass == phy_AOSCLASS_STALE) return phy_SENSINGSTATE_FRESHNESSLIMITED;
  if (phy_AccClass == phy_ACCCLASS_LIMITED || phy_CRBClass == phy_CRBCLASS_LOOSE) return phy_SENSINGSTATE_ACCURACYLIMITED;
  if (phy_PdClass == phy_PDCLASS_LOW) return phy_SENSINGSTATE_PROBABILITYLIMITED;
  if (phy_RfaClass == phy_RFACLASS_HIGH) return phy_SENSINGSTATE_FALSEALARMLIMITED;
  if (phy_CapClass == phy_CAPCLASS_LIMITED) return phy_SENSINGSTATE_CAPACITYLIMITED;
  if (phy_CoverageClass == phy_COVERAGECLASS_LIMITED) return phy_SENSINGSTATE_COVERAGELIMITED;
  return phy_SENSINGSTATE_SENSINGQOSOK;
}

