const mac_MacReason_t mac_REASON_NONE=0, mac_REASON_RESOURCE_EXHAUSTED=1, mac_REASON_PHY_ACK_TIMEOUT=2, mac_REASON_QUEUE_CRITICAL=3, mac_REASON_SENS_COMM_CONFLICT=4, mac_REASON_STALE_PHY_KPI=5, mac_REASON_BUFFER_OVERFLOW=6;

mac_QueueClass_t mac_queueClass = mac_Q_EMPTY;
mac_BufferClass_t mac_bufferClass = mac_B_SAFE;
mac_DelayClass_t mac_delayClass = mac_D_OK;
mac_DropClass_t mac_dropClass = mac_DROP_NONE;
mac_ResourceClass_t mac_resourceClass = mac_RES_FREE;
mac_ResourceClass_t mac_mappedResourceClass = mac_RES_FREE;
mac_SensingDemand_t mac_sensingDemand = mac_SENS_NOMINAL;
mac_CommDemand_t mac_commDemand = mac_COMM_NOMINAL;
mac_KPIFreshnessClass_t mac_kpiFreshnessClass = mac_KPI_MISSING;
mac_ScheduleMode_t mac_scheduleMode = mac_SCH_IDLE;
mac_MacReason_t mac_macReason = mac_REASON_NONE;
bool mac_mac_report_pending = false;
bool mac_mac_report_sent = false;
bool mac_silent_accept = false;
bool mac_phy_ack_timeout = false;
