int app_svc_risk() {
  return 3*app_missedDetectionClass + 2*app_falseAlarmClass
       + 2*app_detectionFreshnessClass + app_updatePeriodClass
       + app_accuracyClass + app_coverageClass + app_criticalityClass;
}

bool app_detection_kpi_consistent() {
  return !(app_pdClass == app_PD_OK
           && app_missedDetectionClass == app_MISS_CRITICAL)
      && !(app_pdClass == app_PD_FAILED
           && app_missedDetectionClass == app_MISS_OK);
}

bool app_pd_req_satisfied() {
  return (app_pdMinClass == app_REQ_STRICT && app_pdClass == app_PD_OK)
      || (app_pdMinClass == app_REQ_NORMAL && app_pdClass != app_PD_FAILED)
      || (app_pdMinClass == app_REQ_RELAXED);
}

bool app_pfa_req_satisfied() {
  return (app_pfaMaxClass == app_REQ_STRICT && app_falseAlarmClass == app_FA_OK)
      || (app_pfaMaxClass == app_REQ_NORMAL && app_falseAlarmClass != app_FA_CRITICAL)
      || (app_pfaMaxClass == app_REQ_RELAXED);
}

bool app_pmiss_req_satisfied() {
  return (app_pmissMaxClass == app_REQ_STRICT && app_missedDetectionClass == app_MISS_OK)
      || (app_pmissMaxClass == app_REQ_NORMAL && app_missedDetectionClass != app_MISS_CRITICAL)
      || (app_pmissMaxClass == app_REQ_RELAXED);
}

bool app_freshness_req_satisfied() {
  return (app_sensingFreshnessBoundClass == app_REQ_STRICT
          && app_detectionFreshnessClass == app_DET_FRESH)
      || (app_sensingFreshnessBoundClass == app_REQ_NORMAL
          && app_detectionFreshnessClass != app_DET_EXPIRED)
      || (app_sensingFreshnessBoundClass == app_REQ_RELAXED);
}

bool app_update_req_satisfied() {
  return (app_sensingUpdateBoundClass == app_REQ_STRICT
          && app_updatePeriodClass == app_UPD_OK)
      || (app_sensingUpdateBoundClass == app_REQ_NORMAL
          && app_updatePeriodClass != app_UPD_VIOLATED)
      || (app_sensingUpdateBoundClass == app_REQ_RELAXED);
}

bool app_quality_req_satisfied(app_RequirementClass_t app_req, app_QualityClass_t app_value) {
  return (app_req == app_REQ_STRICT && app_value == app_OK)
      || (app_req == app_REQ_NORMAL && app_value != app_FAILED)
      || (app_req == app_REQ_RELAXED);
}

bool app_sensing_req_satisfied() {
  return app_freshness_req_satisfied()
      && app_update_req_satisfied()
      && app_pd_req_satisfied()
      && app_pfa_req_satisfied()
      && app_pmiss_req_satisfied()
      && app_quality_req_satisfied(app_accuracyBoundClass, app_accuracyClass)
      && app_quality_req_satisfied(app_coverageBoundClass, app_coverageClass);
}

bool app_sla_sens_violated() {
  return !app_detection_kpi_consistent()
      || app_detectionFreshnessClass == app_DET_EXPIRED
      || app_updatePeriodClass == app_UPD_VIOLATED
      || app_falseAlarmClass == app_FA_CRITICAL
      || app_missedDetectionClass == app_MISS_CRITICAL
      || app_pdClass == app_PD_FAILED
      || app_accuracyClass == app_FAILED
      || app_coverageClass == app_FAILED;
}

bool app_sla_sens_warn() {
  return app_detection_kpi_consistent()
      && !app_sla_sens_violated()
      && !app_sensing_req_satisfied();
}

bool app_sla_sens_ok() {
  return app_detection_kpi_consistent()
      && app_sensing_req_satisfied()
      && !app_sla_sens_violated();
}

bool app_gAdmissionRequest() {
  return app_serviceClass == app_SVC_UAV
      || app_serviceClass == app_SVC_ISAC_SENSING
      || app_demandClass == app_DEMAND_JOINT
      || app_demandClass == app_DEMAND_SENS;
}

bool app_gSafetyAllowsDegraded() {
  return app_criticalityClass != app_CRIT_SAFETY
      || (app_sla_sens_ok()
          && app_degradedReason == app_DEG_COMM_LIMITED);
}

bool app_gAcceptDegraded() {
  return app_admissionClass == app_ADM_DEGRADED
      && app_degraded_allowed
      && app_degradedReason != app_DEG_NONE
      && app_gSafetyAllowsDegraded();
}

bool app_gRejectDegraded() {
  return app_admissionClass == app_ADM_DEGRADED && !app_gAcceptDegraded();
}

bool app_gSlaWarning() {
  return app_slaClass == app_SLA_WARN || app_sla_sens_warn();
}

bool app_gSlaViolation() {
  return app_slaClass == app_SLA_VIOLATED || app_sla_sens_violated();
}

bool app_gSafetyCriticalViolation() {
  return app_criticalityClass == app_CRIT_SAFETY && app_gSlaViolation();
}

